/* ============ HISTORY ============ */
historia: [
  { y: '13,000 years ago', n: 'The first peoples', d: 'Humans are already here, as shown at Lagoa Santa, Minas Gerais, where the skull of “Luzia” was found, and in the paintings of Serra da Capivara, Piauí.', t: 'First peoples' },
  { y: 'Before 1500', n: 'A populated land', d: 'Millions of people and over a thousand languages. In the Amazon there are traces of large settlements. Tupi, Jê and other groups occupy almost everything.', t: 'First peoples' },
  { y: '1500', n: 'Cabral’s fleet', d: 'Pedro Álvares Cabral reaches Bahia. Pero Vaz de Caminha’s letter is considered Brazil’s “birth certificate”.', t: 'Colony' },
  { y: '1534', n: 'The captaincies', d: 'Portugal divides the land into strips granted to nobles. In 1549, Salvador becomes the first capital and the Jesuits arrive.', t: 'Colony' },
  { y: '1550', n: 'The African slave trade', d: 'The largest slave trade in the Americas begins. It lasts over 300 years and brings almost 5 million people.', t: 'Slavery' },
  { y: '1630', n: 'The Dutch in the Northeast', d: 'The Dutch West India Company takes Recife and Olinda for the sugar. Maurice of Nassau governs from 1637 to 1644, and the Dutch are expelled in 1654.', t: 'Colony' },
  { y: '1695', n: 'The fall of Palmares', d: 'Zumbi dies, leader of the largest quilombo in history, at Serra da Barriga, Alagoas, which had held out for almost a hundred years.', t: 'Slavery' },
  { y: '1695–1760', n: 'The gold rush', d: 'Gold in Minas Gerais brings settlement to the interior and baroque wealth, with Ouro Preto and Aleijadinho.', t: 'Colony' },
  { y: '1789', n: 'The Minas Conspiracy', d: 'A plot against gold taxes. Tiradentes is hanged in 1792.', t: 'Colony' },
  { y: '1808', n: 'The court flees to Rio', d: 'Dom João VI escapes Napoleon, brings the Portuguese court, opens the ports and creates Banco do Brasil and the Botanical Garden.', t: 'Empire' },
  { y: '1822', n: 'Independence', d: 'Dom Pedro I, son of the Portuguese king, breaks Brazil from Portugal on the banks of the Ipiranga and becomes emperor.', t: 'Empire' },
  { y: '1840', n: 'The reign of Dom Pedro II', d: 'Almost 50 years of relative stability, with coffee and immigration, while the country remains a slave society.', t: 'Empire' },
  { y: '1864', n: 'The Paraguayan War', d: 'South America’s largest conflict. Brazil, Argentina and Uruguay destroy Paraguay, with many Black soldiers fighting for Brazil.', t: 'Empire' },
  { y: '1888', n: 'Abolition', d: 'The Golden Law frees the enslaved, with no compensation or land. Brazil was the last country in the Americas to do so.', t: 'Slavery' },
  { y: '1889', n: 'The Republic', d: 'A military coup topples the monarchy. So begins the “Coffee with Milk Republic”, dominated by São Paulo and Minas Gerais.', t: 'Republic' },
  { y: '1908', n: 'The Japanese and other immigrants', d: 'The Kasato Maru brings the first Japanese. Italians, Germans, Arabs and Jews also came and changed the South and Southeast.', t: 'Republic' },
  { y: '1922', n: 'Modern Art Week', d: 'In São Paulo, young artists break with Europe. The Cannibalist Movement grows out of it.', t: 'Culture' },
  { y: '1930', n: 'The Vargas Era', d: 'Getúlio Vargas takes power, creates the labour code, Petrobras and the dictatorial Estado Novo, until 1945. He returns in 1951 and takes his own life in 1954.', t: 'Republic' },
  { y: '1950', n: 'The Maracanazo', d: 'The defeat to Uruguay in the home World Cup final is a national tragedy that Nelson Rodrigues called “our Hiroshima”.', t: 'Culture' },
  { y: '1958', n: 'The first title and bossa nova', d: 'Brazil wins the World Cup, with Pelé aged 17, and João Gilberto releases Chega de Saudade.', t: 'Culture' },
  { y: '1960', n: 'Brasília', d: 'JK opens the new capital on the Central Plateau, in 41 months, designed by Lúcio Costa and Niemeyer.', t: 'Republic' },
  { y: '1964', n: 'The military coup', d: 'The military topples João Goulart. The dictatorship lasts 21 years, with censorship, torture and hundreds of dead and disappeared.', t: 'Dictatorship' },
  { y: '1984', n: 'Diretas Já', d: 'Millions take to the streets for direct presidential elections. The amendment is defeated, but the dictatorship ends the following year.', t: 'Dictatorship' },
  { y: '1988', n: 'The Citizen Constitution', d: 'The creation of the SUS public health system, guarantees for Indigenous and quilombola peoples, and democracy restored.', t: 'Democracy' },
  { y: '1994', n: 'The Real Plan', d: 'Hyperinflation ends, after reaching over 2,000% a year. 1994 also brings the fourth World Cup and the death of Senna.', t: 'Democracy' },
  { y: '2003', n: 'Lula and the boom', d: 'The former factory worker becomes president. The commodities boom and Bolsa Família lift millions out of poverty and Brazil leaves the UN Hunger Map.', t: 'Democracy' },
  { y: '2014–2016', n: 'World Cup, Car Wash and Olympics', d: 'The 7–1, the anti-corruption operation, recession, Dilma’s impeachment and the Rio Games.', t: 'Democracy' },
  { y: '2020', n: 'The pandemic', d: 'Brazil records over 700,000 Covid-19 deaths, one of the world’s worst totals.', t: 'Democracy' },
  { y: '2023', n: '8 January', d: 'Bolsonaro supporters storm and ransack Congress, the Presidential Palace and the Supreme Court. In 2025, Bolsonaro is convicted of attempting a coup.', t: 'Democracy' },
  { y: '2025', n: 'Oscar and COP30', d: 'I’m Still Here wins Brazil’s first International Feature Oscar and Belém hosts the UN climate conference.', t: 'Culture' },
  { y: '2026', n: 'Lula’s re-election', d: 'In October, Lula beats Flávio Bolsonaro by 51.79% to 48.21% in a tight election and reaches a fourth term.', t: 'Democracy' }
],

